xpath.script:
(function () {
    var container = document.querySelector('#o_wevent_event_main .container');
    if (!container) { return; }
    var mainCol = container.querySelector('#o_wevent_event_main_col');
    var sidebar = container.querySelector('#o_wevent_event_main_sidebar');
    if (!mainCol || !sidebar) { return; }

    // Build two-column wrapper
    var splitRow = document.createElement('div');
    splitRow.className = 'row g-0 flex-lg-nowrap align-items-start ea-event-two-col';

    var mainWrap = document.createElement('div');
    mainWrap.className = 'col-12 col-lg-8';
    mainWrap.id = 'ea-event-main-wrap';

    var asideWrap = document.createElement('div');
    asideWrap.className = 'col-12 col-lg-4';
    asideWrap.id = 'ea-event-aside-wrap';

    splitRow.appendChild(mainWrap);
    splitRow.appendChild(asideWrap);

    var oldRow = mainCol.parentElement;
    if (oldRow) {
        container.insertBefore(splitRow, oldRow);
    } else {
        container.appendChild(splitRow);
    }

    mainWrap.appendChild(mainCol);
    asideWrap.appendChild(sidebar);

    // Let sidebar fill the new column instead of nested grid sizing
    sidebar.classList.remove('col-lg-4', 'col-12', 'my-3', 'mb-lg-0');
    sidebar.classList.add('w-100');
    sidebar.style.width = '100%';
})();


document.addEventListener('click', function (ev) {
    const minusBtn = ev.target.closest('.ea-qty-minus');
    const plusBtn = ev.target.closest('.ea-qty-plus');
    if (!minusBtn && !plusBtn) {
        return;
    }
    ev.preventDefault();
    const control = (minusBtn || plusBtn).closest('.ea-qty-control');
    if (!control) {
        return;
    }
    const input = control.querySelector('.ea-qty-input');
    const select = control.querySelector('.ea-qty-select');
    if (!input || !select) {
        return;
    }
    const min = parseInt(input.min || '0', 10);
    const max = parseInt(input.max || '0', 10);
    let value = parseInt(input.value || '0', 10);
    if (Number.isNaN(value)) {
        value = min;
    }
    if (minusBtn) {
        value = Math.max(min, value - 1);
    } else {
        value = Math.min(max, value + 1);
    }
    input.value = String(value);
    select.value = String(value);
    select.dispatchEvent(new Event('change', { bubbles: true }));
});

document.addEventListener('input', function (ev) {
    const input = ev.target.closest('.ea-qty-input');
    if (!input) {
        return;
    }
    const control = input.closest('.ea-qty-control');
    const select = control ? control.querySelector('.ea-qty-select') : null;
    if (!select) {
        return;
    }
    const min = parseInt(input.min || '0', 10);
    const max = parseInt(input.max || '0', 10);
    let value = parseInt(input.value || '0', 10);
    if (Number.isNaN(value)) {
        value = min;
    }
    value = Math.max(min, Math.min(max, value));
    input.value = String(value);
    select.value = String(value);
    select.dispatchEvent(new Event('change', { bubbles: true }));
});

t.script:
document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('.ea-single-submit-form').forEach(function (form) {
        form.addEventListener('submit', function () {
            if (form.dataset.submitted === '1') {
                return false;
            }
            form.dataset.submitted = '1';
            form.querySelectorAll('.ea-single-submit-button').forEach(function (button) {
                button.disabled = true;
                button.dataset.originalText = button.innerHTML;
                button.innerHTML = button.dataset.loadingText || 'Processing...';
            });
        });
    });
});

xpath.script:
(function () {
    var path = (window.location && window.location.pathname) || '';
    if (!/\/register(?:[/?]|$)/.test(path)) {
        return;
    }
    var section = document.querySelector('#o_wevent_event_main');
    var container = section && section.querySelector(':scope > .container');
    var mainCol = container && container.querySelector('#o_wevent_event_main_col');
    if (!container || !mainCol) {
        return;
    }

    // Move navbar/breadcrumbs just above the container if still inside the grid
    var submenu = container.querySelector('#o_wevent_event_submenu');
    if (submenu && submenu.parentElement !== section) {
        section.insertBefore(submenu, container);
    }

    // Re-home gallery and description elements into the main column
    var gallery = section.querySelector('.ea-gallery-section') || section.querySelector('.ea-hero-card');
    var desc = section.querySelector('.ea-desc-truncate') || section.querySelector('[itemprop="description"]');
    var anchor = mainCol.firstElementChild;

    [gallery, desc].forEach(function (el) {
        if (el && !mainCol.contains(el)) {
            mainCol.insertBefore(el, anchor || mainCol.firstChild);
        }
    });
})();
